void qb_mid_assign(qb_string** target, int32_t start, int32_t length, qb_string* value) {
    if (!target || !*target || !value) return;
    qb_string* s = *target;
    size_t s_len = qb_string_len(s);
    if (start < 1 || (size_t)start > s_len) return;
    size_t idx = (size_t)(start - 1);
    size_t max_len = s_len - idx;
    size_t replace_len;
    if (length < 0) {
        size_t value_len = qb_string_len(value);
        replace_len = (value_len < max_len) ? value_len : max_len;
    } else {
        replace_len = ((size_t)length < max_len) ? (size_t)length : max_len;
        size_t value_len = qb_string_len(value);
        if (replace_len > value_len) replace_len = value_len;
    }
    // Build new string: left part + replacement + right part
    qb_string* left_part = (idx > 0) ? qb_left(s, (int32_t)idx) : qb_string_empty();
    qb_string* replace_part = (replace_len > 0) ? qb_left(value, (int32_t)replace_len) : qb_string_empty();
    size_t right_start = idx + replace_len;
    qb_string* right_part = (right_start < s_len) ? qb_right(s, (int32_t)(s_len - right_start + 1)) : qb_string_empty();
    qb_string* temp = qb_string_concat(left_part, replace_part);
    qb_string* new_str = qb_string_concat(temp, right_part);
    // Clean up temporary strings
    if (left_part) qb_string_release(left_part);
    if (replace_part) qb_string_release(replace_part);
    if (right_part) qb_string_release(right_part);
    if (temp) qb_string_release(temp);
    // Release old target and set new string
    qb_string_release(*target);
    *target = new_str;
}

